/* ---------- Europe (2/2) : Balkans, Europe centrale, Nord, Est, Îles Britanniques ---------- */
const D43 = [
{ id:'sarma-bosniaque', c:'eu', lat:44.202, lon:17.908, base:6, prep:50, cook:120, diff:2, tags:['comfort','slow','beef'],
  art:{v:'pot',bg:'#2f3328',plate:'#f0e4c8',style:'stew',food:['#c9a878','#e8dcb8','#8f5a3a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Sarma de Bosnie',en:'Bosnian sarma'},
  p:{fr:'Travnik, Bosnie-Herzégovine',en:'Travnik, Bosnia and Herzegovina'},
  d:{fr:"Des feuilles de chou aigre roulées autour de viande et de riz, mijotées deux heures sur un lit de côtes fumées. Le chou est fermenté entier, en tête, dans des tonneaux — chaque famille bosnienne a le sien à la cave.",
     en:"Sour cabbage leaves rolled around meat and rice, stewed for two hours on a bed of smoked ribs. The cabbage is fermented whole, in heads, in barrels — every Bosnian family keeps one in the cellar."},
  i:[['fermented_cabbage',1,'pc'],['ground_beef',500,'g'],['ground_lamb',300,'g'],['long_grain_rice',150,'g'],['onion',3,'pc'],['smoked_pork_ribs',500,'g'],['sweet_paprika',2,'tbsp'],['garlic',5,'clove'],['egg',1,'pc'],['lard',60,'g'],['flour',2,'tbsp'],['bay_leaf',3,'pc'],['parsley',4,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Détachez les feuilles du chou fermenté, rincez-les si elles sont très acides et aplatissez la nervure centrale au couteau.","Faites fondre l'oignon, laissez-le refroidir, puis mêlez-le aux viandes, au riz cru, à l'ail, à l'œuf et au paprika.","Déposez une cuillerée de farce sur chaque feuille, repliez les côtés et roulez serré, en rentrant les extrémités.","Tapissez le fond d'une cocotte de côtes fumées et de chou haché, rangez les rouleaux debout, serrés.","Couvrez d'eau, posez une assiette dessus pour les maintenir, et laissez mijoter 2 heures. Liez d'un roux de saindoux et de paprika à la fin."],
     en:["Separate the leaves of the fermented cabbage, rinse them if very sour and flatten the central rib with a knife.","Soften the onion, let it cool, then mix with the meats, raw rice, garlic, egg and paprika.","Place a spoonful of filling on each leaf, fold in the sides and roll tightly, tucking in the ends.","Line a pot with the smoked ribs and chopped cabbage, and pack the rolls upright, tightly.","Cover with water, set a plate on top to hold them down, and simmer for 2 hours. Thicken with a lard and paprika roux at the end."]} },

{ id:'jota-triestina', c:'eu', lat:45.649, lon:13.777, base:6, prep:25, cook:120, diff:1, tags:['legume','soup','slow'],
  art:{v:'pot',bg:'#2f3328',plate:'#f0e4c8',style:'soup',food:['#c9a878','#8f6a4a','#e8dcb8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Jota triestine',en:'Triestine jota'},
  p:{fr:'Trieste, Frioul, Italie',en:'Trieste, Friuli, Italy'},
  d:{fr:"Une soupe de haricots, de choucroute et de pommes de terre, à la frontière de trois cuisines : italienne, slovène et autrichienne. Trieste fut le port des Habsbourg, et sa cuisine n'a jamais choisi son camp.",
     en:"A soup of beans, sauerkraut and potato, on the border of three cuisines: Italian, Slovene and Austrian. Trieste was the Habsburg port, and its cooking never picked a side."},
  i:[['cannellini_beans',400,'g'],['sauerkraut',600,'g'],['potato',600,'g'],['smoked_pork_ribs',500,'g'],['smoked_bacon',150,'g'],['onion',2,'pc'],['garlic',4,'clove'],['flour',2,'tbsp'],['lard',60,'g'],['bay_leaf',3,'pc'],['cumin',1,'tsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites tremper les haricots une nuit, puis cuisez-les 1 heure avec les côtes fumées et le laurier.","Faites cuire la choucroute à part, dans peu d'eau avec le cumin, 40 minutes : cuite avec les haricots, son acidité les durcirait.","Ajoutez les pommes de terre en gros cubes aux haricots et poursuivez 25 minutes.","Écrasez un tiers des haricots et des pommes de terre à la fourchette pour lier la soupe.","Faites un roux brun de saindoux, farine, oignon et ail, versez-le dans la marmite avec la choucroute, et laissez marier 20 minutes."],
     en:["Soak the beans overnight, then cook them for 1 hour with the smoked ribs and bay.","Cook the sauerkraut separately in a little water with the cumin for 40 minutes: cooked with the beans, its acidity would toughen them.","Add the potatoes in large cubes to the beans and continue for 25 minutes.","Crush a third of the beans and potatoes with a fork to thicken the soup.","Make a brown roux of lard, flour, onion and garlic, stir it into the pot with the sauerkraut, and let it marry for 20 minutes."]} },

{ id:'gibanica', c:'eu', lat:44.787, lon:20.449, base:8, prep:40, cook:50, diff:2, tags:['cheese','bake','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ecd8',style:'pastry',food:['#e0b45a','#f4f0e6','#f2dfa8','#c98a2c'],garnish:'#7fae6a'},
  n:{fr:'Gibanica',en:'Gibanica'},
  p:{fr:'Belgrade, Serbie',en:'Belgrade, Serbia'},
  d:{fr:"Des feuilles de pâte froissées et empilées avec du fromage frais et des œufs, cuites jusqu'à devenir dorées et gonflées. Le nom vient de gibati, plier : la pâte n'est jamais lisse, toujours chiffonnée.",
     en:"Sheets of pastry crumpled and layered with fresh cheese and eggs, baked until golden and puffed. The name comes from gibati, to fold: the pastry is never smooth, always crumpled."},
  i:[['filo_pastry',500,'g'],['farmer_cheese',700,'g'],['feta',200,'g'],['egg',6,'pc'],['sour_cream',400,'ml'],['sparkling_water',150,'ml'],['olive_oil',150,'ml'],['butter',80,'g'],['salt',null,'']],
  s:{fr:["Écrasez les fromages à la fourchette, mêlez-les aux œufs battus et à la moitié de la crème aigre.","Beurrez un plat et posez deux feuilles de pâte à plat, en les laissant déborder.","Trempez rapidement les feuilles suivantes dans l'appareil, froissez-les à la main et disposez-les en vagues dans le plat.","Alternez jusqu'à épuisement, en terminant par deux feuilles lisses rabattues sur le dessus.","Mêlez le reste de crème à l'eau gazeuse, versez sur la tourte et enfournez 50 minutes à 180 °C. Laissez tiédir avant de couper."],
     en:["Mash the cheeses with a fork and mix with the beaten eggs and half the sour cream.","Butter a dish and lay two sheets of pastry flat, letting them overhang.","Dip the next sheets briefly in the mixture, crumple them by hand and arrange them in waves in the dish.","Alternate until everything is used, finishing with two smooth sheets folded over the top.","Mix the remaining cream with the sparkling water, pour it over the pie and bake for 50 minutes at 180°C. Let it cool a little before cutting."]} },

{ id:'jagnjetina-ispod-sacha', c:'eu', lat:42.442, lon:19.263, base:8, prep:30, cook:150, diff:2, tags:['lamb','slow','festive'],
  art:{v:'pot',bg:'#2b2419',plate:'#f0e4c8',style:'grill',food:['#8f5a3a','#c9754a','#e8d8b8','#e0b45a'],garnish:'#7fae6a'},
  n:{fr:'Agneau sous la cloche',en:'Lamb under the bell'},
  p:{fr:'Podgorica, Monténégro',en:'Podgorica, Montenegro'},
  d:{fr:"De l'agneau et des pommes de terre cuits sous une cloche de fonte enterrée sous la braise. Le sač se pratique dans tous les Balkans, mais le Monténégro en a fait le repas obligé des retours de famille.",
     en:"Lamb and potatoes cooked under a cast-iron bell buried in embers. The sač is found across the Balkans, but Montenegro has made it the obligatory meal of family reunions."},
  i:[['lamb_shoulder',2,'kg'],['potato',1.5,'kg'],['onion',3,'pc'],['carrot',3,'pc'],['garlic',10,'clove'],['rosemary',4,'sprig'],['white_wine',250,'ml'],['olive_oil',120,'ml'],['bay_leaf',3,'pc'],['kajmak',200,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Piquez l'agneau d'éclats d'ail et frottez-le d'huile, de romarin et de sel une heure à l'avance.","Taillez les pommes de terre et les légumes en gros morceaux : petits, ils fondraient en deux heures et demie.","Disposez le tout dans un large plat de fonte, arrosez de vin blanc et d'un verre d'eau.","Couvrez de la cloche et enfouissez-la sous la braise, ou enfournez à 200 °C sous un couvercle lourd.","Laissez cuire 2 heures sans jamais soulever, puis découvrez 20 minutes pour dorer. Servez avec du kajmak."],
     en:["Stud the lamb with slivers of garlic and rub it with oil, rosemary and salt an hour ahead.","Cut the potatoes and vegetables into large pieces: small ones would dissolve over two and a half hours.","Arrange everything in a wide cast-iron dish and pour over the white wine and a glass of water.","Cover with the bell and bury it under embers, or bake at 200°C under a heavy lid.","Cook for 2 hours without ever lifting it, then uncover for 20 minutes to brown. Serve with kajmak."]} },

{ id:'jota-slovene', c:'eu', lat:46.056, lon:14.506, base:6, prep:30, cook:90, diff:1, tags:['legume','soup','comfort'],
  art:{v:'pot',bg:'#2f3328',plate:'#f0e4c8',style:'soup',food:['#8f6a4a','#c9a878','#e8dcb8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Ričet',en:'Ričet'},
  p:{fr:'Ljubljana, Slovénie',en:'Ljubljana, Slovenia'},
  d:{fr:"Un potage d'orge perlé et de haricots au lard fumé, épais à tenir la cuillère. C'était la soupe des soldats austro-hongrois, servie dans toutes les casernes de l'Empire, et la Slovénie l'a gardée pour elle.",
     en:"A soup of pearl barley and beans with smoked pork, thick enough to hold a spoon. It was the soup of Austro-Hungarian soldiers, served in every barracks of the Empire, and Slovenia kept it for itself."},
  i:[['barley',250,'g'],['cannellini_beans',250,'g'],['smoked_pork_ribs',500,'g'],['smoked_bacon',150,'g'],['carrot',3,'pc'],['celery_root',1,'pc'],['potato',400,'g'],['onion',2,'pc'],['garlic',4,'clove'],['flour',2,'tbsp'],['lard',60,'g'],['bay_leaf',3,'pc'],['marjoram',1,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites tremper l'orge et les haricots séparément une nuit.","Mettez-les à l'eau froide avec les côtes fumées et le laurier, et laissez frémir 1 heure.","Ajoutez carotte, céleri-rave et pomme de terre en dés, et poursuivez 30 minutes.","Faites un roux blond avec le saindoux, la farine, l'oignon et l'ail, et versez-le dans la marmite.","Effilochez la viande, remettez-la, ajoutez la marjolaine et laissez marier 10 minutes. La soupe doit être très épaisse."],
     en:["Soak the barley and beans separately overnight.","Put them in cold water with the smoked ribs and bay, and simmer for 1 hour.","Add the carrot, celeriac and potato in dice, and continue for 30 minutes.","Make a pale roux with the lard, flour, onion and garlic, and stir it into the pot.","Shred the meat, return it, add the marjoram and let it marry for 10 minutes. The soup should be very thick."]} },

{ id:'pierogi-ruskie-zapiekane', c:'eu', lat:51.247, lon:22.568, base:6, prep:75, cook:25, diff:2, tags:['veg','comfort','bake'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ecd8',style:'pastry',food:['#e0b45a','#f0e8d0','#c9a878','#f4f0e6'],garnish:'#7fae6a'},
  n:{fr:'Pierogi aux lentilles et au sarrasin',en:'Lentil and buckwheat pierogi'},
  p:{fr:'Lublin, Pologne',en:'Lublin, Poland'},
  d:{fr:"Des raviolis polonais farcis de sarrasin, de lentilles et de champignons — la version de carême, sans viande ni fromage. Le sarrasin, kasza gryczana, est à la Pologne de l'Est ce que la pomme de terre est à l'Ouest.",
     en:"Polish dumplings filled with buckwheat, lentils and mushrooms — the Lenten version, without meat or cheese. Buckwheat, kasza gryczana, is to eastern Poland what the potato is to the west."},
  i:[['flour',500,'g'],['warm_water',250,'ml'],['egg',1,'pc'],['buckwheat_flour',200,'g'],['brown_lentils',150,'g'],['dried_morels',30,'g'],['onion',3,'pc'],['butter',100,'g'],['sour_cream',300,'ml'],['marjoram',1,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Pétrissez la farine, l'eau tiède, l'œuf et le sel 10 minutes, puis laissez reposer 40 minutes sous un linge.","Faites cuire le sarrasin et les lentilles séparément, et trempez les champignons une heure.","Faites blondir deux oignons dans le beurre, ajoutez les champignons hachés, puis mêlez au sarrasin, aux lentilles et à la marjolaine.","Étalez la pâte à 2 mm, découpez des disques de 8 cm, garnissez et scellez en pinçant fermement.","Pochez 4 minutes, puis faites-les dorer à la poêle avec le troisième oignon émincé. Servez avec la crème aigre."],
     en:["Knead the flour, warm water, egg and salt for 10 minutes, then rest for 40 minutes under a cloth.","Cook the buckwheat and lentils separately, and soak the mushrooms for an hour.","Turn two onions golden in the butter, add the chopped mushrooms, then mix with the buckwheat, lentils and marjoram.","Roll the dough to 2 mm, cut 8 cm discs, fill them and seal by pinching firmly.","Poach for 4 minutes, then fry them golden with the third onion, sliced. Serve with the sour cream."]} },

{ id:'koprovka', c:'eu', lat:50.213, lon:15.833, base:6, prep:25, cook:120, diff:2, tags:['beef','comfort','sunday'],
  art:{v:'plate',bg:'#2f3326',plate:'#f4ecd8',style:'stew',food:['#f0e8d0','#e8dcc0','#7fae5a','#f4f0e6'],garnish:'#6fbf8f'},
  n:{fr:'Koprová omáčka',en:'Koprová omáčka'},
  p:{fr:'Hradec Králové, Bohême, Tchéquie',en:'Hradec Králové, Bohemia, Czechia'},
  d:{fr:"Du bœuf bouilli sous une sauce blanche à l'aneth, aigre-douce de vinaigre et de sucre, avec un œuf dur et des knedlíky. C'est le plat de cantine tchèque par excellence, aimé et moqué à parts égales.",
     en:"Boiled beef under a white dill sauce, sweet-sour with vinegar and sugar, with a hard-boiled egg and knedlíky. The Czech canteen dish par excellence, loved and mocked in equal measure."},
  i:[['beef_brisket',1,'kg'],['carrot',2,'pc'],['onion',2,'pc'],['bay_leaf',2,'pc'],['allspice',5,'pc'],['butter',80,'g'],['flour',60,'g'],['heavy_cream',300,'ml'],['dill',3,'bunch'],['white_wine_vinegar',3,'tbsp'],['sugar',2,'tbsp'],['egg',6,'pc'],['bread_dumplings',600,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites cuire la poitrine 1 h 45 avec les légumes, le laurier et le piment de la Jamaïque ; gardez le bouillon filtré.","Faites un roux blond avec le beurre et la farine, sans le laisser colorer, et mouillez-le d'un litre de bouillon chaud, en fouettant.","Laissez cuire 15 minutes à petit feu pour ôter le goût de farine, puis ajoutez la crème.","Hachez l'aneth très finement et ajoutez-le hors du feu : cuit, il perd tout son parfum.","Équilibrez au vinaigre et au sucre — la sauce doit être franchement aigre-douce — et servez sur la viande tranchée, avec un demi-œuf dur et des knedlíky."],
     en:["Cook the brisket for 1¾ hours with the vegetables, bay and allspice; keep the strained broth.","Make a pale roux with the butter and flour, without letting it colour, and whisk in a litre of hot broth.","Cook for 15 minutes over low heat to lose the floury taste, then add the cream.","Chop the dill very finely and add it off the heat: cooked, it loses all its scent.","Balance with vinegar and sugar — the sauce should be frankly sweet-sour — and serve over the sliced meat with half a hard-boiled egg and knedlíky."]} },

{ id:'szegedi-gulyas', c:'eu', lat:46.900, lon:19.692, base:6, prep:30, cook:120, diff:1, tags:['pork','slow','comfort'],
  art:{v:'pot',bg:'#33251c',plate:'#f0e4c8',style:'stew',food:['#c9402c','#e0913a','#f0e8d0','#8f5a3a'],garnish:'#7fae6a'},
  n:{fr:'Goulasch de Szeged',en:'Székely gulyás'},
  p:{fr:'Kecskemét, Hongrie',en:'Kecskemét, Hungary'},
  d:{fr:"Du porc au paprika et à la choucroute, lié à la crème aigre. Il ne doit rien à la ville de Szeged mais à József Székely, archiviste hongrois qui, arrivé tard à l'auberge, se fit servir un mélange de restes.",
     en:"Pork with paprika and sauerkraut, enriched with sour cream. It owes nothing to the town of Szeged but to József Székely, a Hungarian archivist who, arriving late at the inn, was served a mixture of leftovers."},
  i:[['pork_shoulder',1.2,'kg'],['sauerkraut',700,'g'],['onion',500,'g'],['sweet_paprika',3,'tbsp'],['lard',80,'g'],['garlic',5,'clove'],['caraway',1,'tbsp'],['sour_cream',300,'ml'],['flour',2,'tbsp'],['bay_leaf',2,'pc'],['ripe_tomato',200,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites fondre les oignons finement émincés dans le saindoux 20 minutes, jusqu'à ce qu'ils se défassent.","Retirez du feu, incorporez le paprika et remuez aussitôt : brûlé, il rendrait le plat amer.","Ajoutez le porc en cubes, l'ail, le carvi et la tomate, mouillez d'un verre d'eau et laissez mijoter 1 heure à couvert.","Ajoutez la choucroute rincée et pressée, et poursuivez 40 minutes.","Délayez la crème aigre avec la farine et une louche de jus tiède, versez hors du feu et ne faites plus bouillir."],
     en:["Soften the finely sliced onions in the lard for 20 minutes, until they collapse.","Take off the heat, stir in the paprika at once: scorched, it would make the dish bitter.","Add the diced pork, garlic, caraway and tomato, moisten with a glass of water and simmer covered for 1 hour.","Add the rinsed and squeezed sauerkraut, and continue for 40 minutes.","Slacken the sour cream with the flour and a ladle of warm juices, stir in off the heat and never let it boil again."]} },

{ id:'bryndzove-pirohy', c:'eu', lat:49.061, lon:19.610, base:4, prep:60, cook:20, diff:2, tags:['cheese','comfort','veg'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ecd8',style:'pastry',food:['#f0e8d0','#e8dcb8','#8f5a3a','#f4f0e6'],garnish:'#7fae6a'},
  n:{fr:'Pirohy à la bryndza',en:'Bryndza pirohy'},
  p:{fr:'Liptovský Mikuláš, Slovaquie',en:'Liptovský Mikuláš, Slovakia'},
  d:{fr:"Des raviolis de pomme de terre farcis de bryndza, ce fromage de brebis frais et salé des bergeries des Tatras. On les arrose de lard fondu et de crème aigre, sans chercher la légèreté.",
     en:"Potato dumplings filled with bryndza, the salty fresh sheep's cheese of the Tatra shepherds' huts. Doused in melted bacon fat and sour cream, with no pretence at lightness."},
  i:[['potato',800,'g'],['flour',300,'g'],['egg',2,'pc'],['bryndza_cheese',400,'g'],['smoked_bacon',200,'g'],['sour_cream',300,'ml'],['onion',1,'pc'],['chives',4,'tbsp'],['butter',60,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites cuire les pommes de terre, écrasez-les au presse-purée et laissez-les refroidir complètement.","Pétrissez-les avec la farine, les œufs et le sel, sans travailler longtemps : trop pétrie, la pâte devient élastique.","Écrasez la bryndza à la fourchette avec un peu de crème aigre et l'oignon râpé.","Étalez la pâte à 3 mm, découpez des disques de 7 cm, garnissez et scellez soigneusement en chassant l'air.","Pochez 5 minutes à l'eau frémissante, égouttez et arrosez de lardons rissolés avec leur graisse, de crème et de ciboulette."],
     en:["Boil the potatoes, rice them and let them cool completely.","Knead with the flour, eggs and salt, without working them long: overworked, the dough turns elastic.","Mash the bryndza with a fork, a little sour cream and the grated onion.","Roll the dough to 3 mm, cut 7 cm discs, fill them and seal carefully, pushing out the air.","Poach for 5 minutes in simmering water, drain and pour over crisped lardons with their fat, cream and chives."]} },

{ id:'smorrebrod-roget-al', c:'eu', lat:55.397, lon:10.388, base:4, prep:25, cook:0, diff:1, tags:['sea','fresh','fast'],
  art:{v:'board',bg:'#2b2a1c',plate:'#f2e6c8',style:'flat',food:['#8f6a4a','#f4f0e6','#e0b45a','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Tartine à l’anguille fumée',en:'Smoked eel smørrebrød'},
  p:{fr:'Nyborg, Fionie, Danemark',en:'Nyborg, Funen, Denmark'},
  d:{fr:"La plus prestigieuse des tartines danoises : anguille fumée, œufs brouillés fermes et ciboulette sur du pain de seigle noir. L'ordre des couches est codifié, et l'on ne mange jamais deux smørrebrød dans le désordre.",
     en:"The grandest of Danish open sandwiches: smoked eel, firm scrambled egg and chives on black rye bread. The order of the layers is codified, and one never eats two smørrebrød out of sequence."},
  i:[['smoked_fish',400,'g'],['rye_bread',8,'slice'],['egg',6,'pc'],['heavy_cream',80,'ml'],['salted_butter',100,'g'],['chives',5,'tbsp'],['lemon',1,'pc'],['radish',6,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Choisissez un pain de seigle dense, à peine tranché : il doit tenir la garniture sans plier.","Battez les œufs avec la crème et une pincée de sel, puis faites-les prendre au bain-marie en remuant sans arrêt.","Les œufs doivent rester crémeux mais tenir à la cuillère : trop coulants, ils détremperaient le pain.","Beurrez généreusement le pain jusqu'aux bords — le beurre fait barrière à l'humidité.","Déposez les œufs, puis les filets d'anguille fumée, la ciboulette, quelques rondelles de radis et un trait de citron."],
     en:["Choose a dense rye loaf, barely sliced: it must hold the topping without bending.","Beat the eggs with the cream and a pinch of salt, then set them over a bain-marie, stirring constantly.","The eggs should stay creamy but hold on a spoon: too loose and they would soak the bread.","Butter the bread generously right to the edges — the butter is a barrier against moisture.","Lay on the eggs, then the smoked eel fillets, the chives, a few radish slices and a squeeze of lemon."]} },

{ id:'palt', c:'eu', lat:65.584, lon:22.154, base:4, prep:40, cook:60, diff:2, tags:['pork','comfort','slow'],
  art:{v:'bowl',bg:'#2c3440',plate:'#f0e4c8',style:'stew',food:['#c9a878','#8f5a3a','#f0e8d0','#8f1a3a'],garnish:'#7fae6a'},
  n:{fr:'Palt',en:'Palt'},
  p:{fr:'Luleå, Norrbotten, Suède',en:'Luleå, Norrbotten, Sweden'},
  d:{fr:"De grosses boulettes de pomme de terre crue farcies de lard, pochées une heure et servies avec du beurre et de la confiture d'airelles. Le plat du Nord suédois, dense et roboratif, qui tient au corps une journée entière.",
     en:"Large dumplings of raw potato stuffed with pork, poached for an hour and served with butter and lingonberry jam. The dish of the Swedish north, dense and sustaining, that sees you through a whole day."},
  i:[['potato',1.2,'kg'],['barley_flour',200,'g'],['flour',150,'g'],['smoked_bacon',300,'g'],['onion',1,'pc'],['salted_butter',150,'g'],['lingonberry_jam',250,'g'],['whole_milk',300,'ml'],['allspice',1,'tsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Râpez les pommes de terre crues très finement et pressez-les dans un linge : gardez l'amidon qui se dépose au fond de l'eau.","Mêlez la pulpe pressée, l'amidon récupéré, les deux farines et le sel jusqu'à obtenir une pâte collante.","Taillez le lard en dés, faites-le revenir avec l'oignon et le piment de la Jamaïque, puis laissez refroidir.","Formez des boules de la taille d'un poing autour d'une cuillerée de lard, en scellant bien.","Pochez-les 1 heure dans une eau à peine frémissante et salée ; elles remontent bien avant d'être cuites. Servez avec beurre et airelles."],
     en:["Grate the raw potatoes very finely and squeeze them in a cloth: keep the starch that settles at the bottom of the liquid.","Mix the squeezed pulp, the recovered starch, both flours and the salt into a sticky dough.","Dice the bacon, fry it with the onion and allspice, then let it cool.","Shape fist-sized balls around a spoonful of the pork, sealing them well.","Poach for 1 hour in barely simmering salted water; they float long before they are cooked. Serve with butter and lingonberry."]} },

{ id:'kalarullad', c:'eu', lat:58.386, lon:26.725, base:4, prep:40, cook:60, diff:2, tags:['comfort','beef','bake'],
  art:{v:'plate',bg:'#2f3328',plate:'#f0e4c8',style:'stew',food:['#7fae5a','#c9a878','#f0e8d0','#8f5a3a'],garnish:'#7fae6a'},
  n:{fr:'Rouleaux de chou estoniens',en:'Estonian cabbage rolls'},
  p:{fr:'Tartu, Estonie',en:'Tartu, Estonia'},
  d:{fr:"Des feuilles de chou blanchies enroulées sur une farce de porc et d'orge, dorées au four et arrosées de crème aigre. L'orge remplace le riz : elle poussait là où le riz n'arrivait jamais.",
     en:"Blanched cabbage leaves rolled around a filling of pork and barley, browned in the oven and doused in sour cream. Barley stands in for rice: it grew where rice never reached."},
  i:[['cabbage',1,'pc'],['ground_pork',500,'g'],['barley',150,'g'],['onion',2,'pc'],['egg',1,'pc'],['smoked_bacon',150,'g'],['sour_cream',300,'ml'],['beef_broth',400,'ml'],['marjoram',1,'tbsp'],['butter',60,'g'],['flour',1,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Retirez le trognon du chou et plongez la tête entière 8 minutes dans l'eau bouillante ; détachez les feuilles au fur et à mesure qu'elles s'amollissent.","Faites cuire l'orge perlé 25 minutes et laissez-le refroidir.","Mêlez porc haché, orge, oignon fondu, œuf, marjolaine, sel et poivre.","Aplatissez la nervure de chaque feuille, garnissez et roulez serré en rentrant les côtés.","Rangez les rouleaux dans un plat beurré, couvrez de lardons et de bouillon, et enfournez 50 minutes à 180 °C. Nappez de crème aigre liée à la farine."],
     en:["Cut out the cabbage core and plunge the whole head into boiling water for 8 minutes; peel off the leaves as they soften.","Cook the pearl barley for 25 minutes and let it cool.","Mix the minced pork, barley, softened onion, egg, marjoram, salt and pepper.","Flatten the rib of each leaf, fill and roll tightly, tucking in the sides.","Pack the rolls in a buttered dish, cover with lardons and broth, and bake for 50 minutes at 180°C. Coat with sour cream thickened with flour."]} },

{ id:'sildi-kartuli', c:'eu', lat:56.946, lon:24.106, base:6, prep:30, cook:0, diff:1, tags:['sea','fresh','festive'],
  art:{v:'plate',bg:'#2c2434',plate:'#f4ecd8',style:'salad',food:['#8f1a3a','#f4f0e6','#e0b45a','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Hareng en manteau de betterave',en:'Herring under a beetroot coat'},
  p:{fr:'Riga, Lettonie',en:'Riga, Latvia'},
  d:{fr:"Un mille-feuille froid de hareng salé, de pomme de terre, d'œuf et de betterave, lié à la mayonnaise et servi en couches rose vif. C'est le plat obligé des réveillons baltes, monté la veille pour qu'il prenne.",
     en:"A cold layered dish of salt herring, potato, egg and beetroot, bound with mayonnaise and served in bright pink strata. The obligatory Baltic New Year dish, assembled the day before so it sets."},
  i:[['pickled_herring',400,'g'],['potato',500,'g'],['beetroot',500,'g'],['carrot',300,'g'],['egg',5,'pc'],['onion',2,'pc'],['mayonnaise',400,'g'],['white_vinegar',3,'tbsp'],['sugar',1,'tsp'],['dill',4,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites cuire pommes de terre, carottes et betteraves séparément, en robe des champs, puis laissez-les refroidir entièrement.","Coupez les filets de hareng en petits dés et faites mariner l'oignon haché 15 minutes dans le vinaigre et le sucre.","Râpez chaque légume à la grille épaisse, dans un bol distinct : les couleurs ne doivent jamais se mêler.","Montez dans un plat : hareng, oignon, pomme de terre, mayonnaise, carotte, œuf, mayonnaise, betterave.","Lissez le dessus, filmez et réservez 12 heures au froid. Décorez d'aneth et d'œuf râpé au moment de servir."],
     en:["Boil the potatoes, carrots and beetroot separately in their skins, then cool them completely.","Dice the herring fillets small and marinate the chopped onion for 15 minutes in the vinegar and sugar.","Grate each vegetable coarsely into a separate bowl: the colours must never mix.","Build up in a dish: herring, onion, potato, mayonnaise, carrot, egg, mayonnaise, beetroot.","Smooth the top, cover and chill for 12 hours. Decorate with dill and grated egg to serve."]} },

{ id:'kotleti-pozharskie', c:'eu', lat:56.259, lon:36.732, base:4, prep:40, cook:20, diff:2, tags:['poultry','fry','comfort'],
  art:{v:'plate',bg:'#2f3326',plate:'#f2e6c8',style:'pastry',food:['#e0b45a','#c98a2c','#f0d89a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Côtelettes Pojarski',en:'Pozharsky cutlets'},
  p:{fr:'Torjok, Russie',en:'Torzhok, Russia'},
  d:{fr:"Des croquettes de volaille panées de cubes de pain plutôt que de chapelure, ce qui les hérisse à la cuisson. Pouchkine les recommande dans une lettre en vers : « déjeune à loisir chez Pojarski à Torjok ».",
     en:"Poultry croquettes coated in cubes of bread rather than crumbs, which makes them bristle as they fry. Pushkin recommended them in a letter in verse: 'dine at leisure at Pozharsky's in Torzhok'."},
  i:[['chicken_breast',700,'g'],['butter',180,'g'],['heavy_cream',150,'ml'],['white_bread',6,'slice'],['onion',1,'pc'],['egg',2,'pc'],['flour',80,'g'],['nutmeg',1,'pinch'],['clarified_butter',120,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Hachez la volaille au couteau, en petits dés : le hachoir en ferait une pâte élastique.","Mêlez-la au beurre froid en parcelles, à la crème, à l'oignon fondu et refroidi, à la muscade et au sel ; laissez raffermir une heure au frais.","Taillez le pain rassis en dés minuscules de 3 mm, sans croûte : c'est la vraie panure.","Formez des côtelettes légèrement bombées, farinez, passez à l'œuf battu puis roulez-les dans les cubes de pain.","Faites-les dorer 4 minutes par face dans le beurre clarifié à feu moyen, puis finissez 6 minutes au four à 180 °C."],
     en:["Chop the poultry by knife into small dice: a mincer would turn it into an elastic paste.","Mix it with cold butter in flakes, the cream, softened and cooled onion, nutmeg and salt; chill for an hour to firm up.","Cut stale bread into tiny 3 mm cubes, crusts removed: this is the true coating.","Shape slightly domed cutlets, flour them, dip in beaten egg then roll in the bread cubes.","Fry them 4 minutes a side in clarified butter over medium heat, then finish 6 minutes in a 180°C oven."]} },

{ id:'rasstegai', c:'eu', lat:56.130, lon:40.407, base:8, prep:120, cook:25, diff:2, tags:['sea','bake','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#c9924a','#e0b45a','#f0a878','#f2dfa8'],garnish:'#7fae6a'},
  n:{fr:'Rasstegaï',en:'Rasstegai'},
  p:{fr:'Vladimir, Russie',en:'Vladimir, Russia'},
  d:{fr:"De petits chaussons ouverts au sommet, dans lesquels on verse une cuillerée de bouillon brûlant au moment de servir. Le nom vient de rasstegnout, « dégrafer » : le pâté reste entrouvert comme un col déboutonné.",
     en:"Small pies left open at the top, into which a spoonful of scalding broth is poured just before serving. The name comes from rasstegnut, 'to unfasten': the pie stays ajar like an unbuttoned collar."},
  i:[['flour',600,'g'],['whole_milk',250,'ml'],['fresh_yeast',25,'g'],['sugar',2,'tbsp'],['butter',100,'g'],['egg',3,'pc'],['salmon',400,'g'],['pike',200,'g'],['long_grain_rice',120,'g'],['onion',2,'pc'],['dill',1,'bunch'],['fish_broth',300,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Délayez la levure dans le lait tiède avec le sucre, laissez mousser, puis pétrissez avec la farine, le beurre, un œuf et le sel. Laissez lever 1 h 30.","Faites cuire le riz à l'eau salée et laissez-le refroidir complètement.","Taillez les poissons en dés, mêlez-les au riz, à l'oignon fondu au beurre et à l'aneth ; poivrez généreusement.","Divisez la pâte en boules de 60 g, aplatissez, garnissez et pincez les bords en laissant une ouverture ovale au centre.","Dorez à l'œuf et enfournez 22 minutes à 200 °C. Versez une cuillerée de fumet brûlant dans chaque ouverture au moment de servir."],
     en:["Dissolve the yeast in warm milk with the sugar, let it froth, then knead with the flour, butter, one egg and salt. Prove for 1½ hours.","Cook the rice in salted water and let it cool completely.","Dice the fish, mix with the rice, butter-softened onion and dill; season with plenty of pepper.","Divide the dough into 60 g balls, flatten, fill and pinch the edges shut, leaving an oval opening at the centre.","Glaze with egg and bake for 22 minutes at 200°C. Pour a spoonful of scalding fish stock into each opening as you serve."]} },

{ id:'deruny', c:'eu', lat:50.907, lon:34.798, base:4, prep:25, cook:25, diff:1, tags:['veg','fry','comfort'],
  art:{v:'plate',bg:'#33301f',plate:'#f0e2c0',style:'flat',food:['#e0b45a','#c98a2c','#f2dfa8','#f4f0e6'],garnish:'#7fae6a'},
  n:{fr:'Deruny',en:'Deruny'},
  p:{fr:'Soumy, Ukraine',en:'Sumy, Ukraine'},
  d:{fr:"Les galettes de pommes de terre ukrainiennes, dorées au saindoux et servies sous une cuillerée de crème aigre. La ville de Korosten leur consacre un festival annuel, avec un monument à leur gloire.",
     en:"The Ukrainian potato pancakes, fried golden in lard and served under a spoonful of sour cream. The town of Korosten holds an annual festival in their honour, complete with a monument."},
  i:[['potato',1,'kg'],['onion',1,'pc'],['egg',2,'pc'],['flour',60,'g'],['sour_cream',300,'ml'],['lard',150,'g'],['mushroom',250,'g'],['garlic',3,'clove'],['dill',4,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Râpez les pommes de terre à la grille fine et l'oignon avec elles : son acidité les empêche de noircir.","Laissez égoutter dix minutes dans une passoire, sans presser, puis récupérez l'amidon déposé au fond du bol.","Mêlez pulpe, amidon, œufs, farine, sel et poivre : la pâte doit être épaisse et à peine coulante.","Faites chauffer le saindoux et déposez des cuillerées aplaties ; laissez prendre 4 minutes sans y toucher.","Retournez, dorez 3 minutes, et servez brûlantes avec la crème aigre, les champignons sautés à l'ail et l'aneth."],
     en:["Grate the potatoes finely and the onion with them: its acidity stops them darkening.","Let them drain for ten minutes in a colander, without pressing, then recover the starch settled at the bottom of the bowl.","Mix pulp, starch, eggs, flour, salt and pepper: the batter should be thick and barely pourable.","Heat the lard and drop in flattened spoonfuls; let them set for 4 minutes untouched.","Turn, brown for 3 minutes, and serve scalding with sour cream, garlic-fried mushrooms and dill."]} },

{ id:'draniki-kolduny', c:'eu', lat:52.425, lon:31.014, base:4, prep:35, cook:30, diff:2, tags:['comfort','pork','fry'],
  art:{v:'plate',bg:'#33301f',plate:'#f0e2c0',style:'flat',food:['#c9924a','#e0b45a','#8f5a3a','#f2dfa8'],garnish:'#7fae6a'},
  n:{fr:'Kolduny de pommes de terre',en:'Potato kolduny'},
  p:{fr:'Homiel, Biélorussie',en:'Homiel, Belarus'},
  d:{fr:"Des galettes de pommes de terre râpées enfermant une farce de viande — la version farcie des draniki. Le mot kolduny veut dire « sorciers » : on ne sait jamais ce qu'ils cachent avant de mordre.",
     en:"Grated potato cakes enclosing a meat filling — the stuffed version of draniki. The word kolduny means 'sorcerers': you never know what they conceal until you bite."},
  i:[['potato',1.2,'kg'],['ground_pork',300,'g'],['onion',2,'pc'],['egg',2,'pc'],['flour',60,'g'],['smoked_bacon',150,'g'],['sour_cream',300,'ml'],['lard',150,'g'],['marjoram',1,'tsp'],['dill',4,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites revenir la viande hachée avec un oignon et la marjolaine, salez généreusement et laissez refroidir.","Râpez les pommes de terre et le second oignon, égouttez-les et récupérez l'amidon du fond.","Mêlez à l'œuf, à la farine et au sel : la pâte doit tenir sur la spatule.","Déposez une cuillerée de pâte dans le saindoux chaud, creusez-la, garnissez d'une noix de farce et recouvrez d'un peu de pâte.","Faites dorer 5 minutes par face à feu moyen — plus vif, l'extérieur brûlerait avant que le cœur ne cuise. Servez avec crème aigre et lardons."],
     en:["Fry the minced pork with one onion and the marjoram, salt generously and let it cool.","Grate the potatoes and the second onion, drain them and recover the starch from the bottom.","Mix with the egg, flour and salt: the batter should hold on a spatula.","Drop a spoonful of batter into the hot lard, hollow it, add a nut of filling and cover with a little more batter.","Brown for 5 minutes a side over medium heat — any hotter and the outside would burn before the centre cooked. Serve with sour cream and lardons."]} },

{ id:'scouse', c:'eu', lat:53.408, lon:-2.991, base:6, prep:25, cook:150, diff:1, tags:['lamb','slow','comfort'],
  art:{v:'pot',bg:'#2b2419',plate:'#f0e4c8',style:'stew',food:['#c9a878','#8f5a3a','#e8dcb8','#e0913a'],garnish:'#7fae6a'},
  n:{fr:'Scouse',en:'Scouse'},
  p:{fr:'Liverpool, Angleterre',en:'Liverpool, England'},
  d:{fr:"Un ragoût d'agneau et de pommes de terre apporté par les marins norvégiens sous le nom de lapskaus. Les habitants de Liverpool en ont tiré leur surnom — Scousers — et leur accent porte le même nom.",
     en:"A stew of lamb and potato brought by Norwegian sailors as lapskaus. The people of Liverpool took their nickname from it — Scousers — and their accent bears the same name."},
  i:[['lamb_shoulder',1,'kg'],['beef_chuck',500,'g'],['potato',1.2,'kg'],['carrot',400,'g'],['onion',3,'pc'],['beef_broth',1.2,'l'],['bay_leaf',3,'pc'],['thyme',2,'sprig'],['worcestershire',1,'tbsp'],['pickled_beans',150,'g'],['beetroot',200,'g'],['rustic_bread',6,'slice'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites colorer les deux viandes en gros morceaux dans une cocotte, par petites quantités.","Ajoutez oignons et carottes en rondelles épaisses, puis le bouillon, le laurier, le thym et le worcestershire.","Laissez mijoter 1 h 30 à couvert, sans y toucher.","Ajoutez la moitié des pommes de terre en gros morceaux, et l'autre moitié râpée : celle-ci se défera et liera le ragoût.","Poursuivez 45 minutes. Servez avec du chou rouge au vinaigre, de la betterave et du pain — c'est la tradition, elle ne se discute pas."],
     en:["Brown both meats in large pieces in a heavy pot, in small batches.","Add the onions and carrots in thick rounds, then the broth, bay, thyme and Worcestershire.","Simmer covered for 1½ hours, untouched.","Add half the potatoes in large pieces and the other half grated: the grated ones collapse and thicken the stew.","Continue for 45 minutes. Serve with pickled red cabbage, beetroot and bread — that is the tradition, and it is not up for discussion."]} },

{ id:'bara-brith', c:'eu', lat:53.140, lon:-4.276, base:10, prep:30, cook:75, diff:1, tags:['sweet','bake','fruit'],
  art:{v:'board',bg:'#2e2419',plate:'#f4ead4',style:'cake',food:['#8f6a4a','#c9924a','#6f4a2a','#f0e0bc'],garnish:'#c9754a'},
  n:{fr:'Bara brith',en:'Bara brith'},
  p:{fr:'Caernarfon, Pays de Galles',en:'Caernarfon, Wales'},
  d:{fr:"Le « pain moucheté » gallois, aux fruits secs trempés une nuit dans le thé noir. Le thé remplace la matière grasse : ce cake ne contient pas une once de beurre, et se mange tartiné à la place.",
     en:"The Welsh 'speckled bread', its dried fruit steeped overnight in black tea. The tea replaces the fat: this loaf contains not an ounce of butter, and is buttered on the plate instead."},
  i:[['raisins',400,'g'],['prunes',150,'g'],['black_tea',400,'ml'],['brown_sugar',250,'g'],['flour',450,'g'],['egg',2,'pc'],['baking_powder',2,'tsp'],['orange_zest',1,'pc'],['cinnamon',1,'tsp'],['nutmeg',1,'pinch'],['honey',2,'tbsp'],['salted_butter',100,'g'],['salt',null,'']],
  s:{fr:["Faites tremper raisins et pruneaux hachés dans le thé chaud avec le sucre roux, toute une nuit.","Le lendemain, les fruits doivent avoir bu presque tout le liquide et avoir triplé de volume.","Incorporez les œufs battus, le zeste et les épices, puis la farine et la levure, sans travailler la pâte.","Versez dans un moule à cake chemisé et enfournez 1 h 15 à 160 °C ; couvrez de papier si le dessus colore trop vite.","Badigeonnez de miel chaud à la sortie et laissez refroidir un jour entier avant de trancher. Se mange beurré."],
     en:["Steep the raisins and chopped prunes in the hot tea with the brown sugar, overnight.","By morning the fruit should have drunk nearly all the liquid and trebled in size.","Work in the beaten eggs, zest and spices, then the flour and baking powder, without overworking.","Pour into a lined loaf tin and bake for 1¼ hours at 160°C; cover with paper if the top colours too fast.","Brush with warm honey as it comes out and let it cool for a full day before slicing. Eaten buttered."]} },

{ id:'dublin-coddle', c:'eu', lat:53.344, lon:-6.267, base:4, prep:20, cook:120, diff:1, tags:['pork','slow','comfort'],
  art:{v:'pot',bg:'#2c3440',plate:'#f0e4c8',style:'stew',food:['#e8dcb8','#c9a878','#f0e8d0','#8f5a3a'],garnish:'#7fae6a'},
  n:{fr:'Coddle de Dublin',en:'Dublin coddle'},
  p:{fr:'Dublin, Irlande',en:'Dublin, Ireland'},
  d:{fr:"Des saucisses et du lard pochés — jamais grillés — avec des pommes de terre et des oignons, dans un bouillon pâle. C'était le plat du jeudi soir, fait avec les restes avant l'abstinence de viande du vendredi.",
     en:"Sausages and bacon poached — never grilled — with potatoes and onions in a pale broth. It was the Thursday night dish, made with leftovers before Friday's abstinence from meat."},
  i:[['pork_sausage',8,'pc'],['smoked_bacon',300,'g'],['potato',1,'kg'],['onion',3,'pc'],['carrot',2,'pc'],['chicken_broth',800,'ml'],['stout',200,'ml'],['parsley',5,'tbsp'],['bay_leaf',2,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Pochez les saucisses et le lard 5 minutes dans l'eau bouillante, puis jetez cette eau : c'est ce qui donne au coddle sa pâleur caractéristique.","Rangez en couches dans une cocotte : oignons, pommes de terre en gros morceaux, carottes, saucisses et lard.","Mouillez du bouillon et de la stout jusqu'à couvrir aux trois quarts seulement.","Ajoutez le laurier, couvrez et laissez mijoter 1 h 45 à feu très doux, sans jamais remuer.","Les pommes de terre du dessus restent entières, celles du fond se défont et lient le bouillon. Couvrez de persil."],
     en:["Poach the sausages and bacon for 5 minutes in boiling water, then throw that water away: this is what gives coddle its characteristic pallor.","Layer in a pot: onions, potatoes in large pieces, carrots, sausages and bacon.","Moisten with the broth and stout to cover only three quarters of the way up.","Add the bay, cover and simmer for 1¾ hours over very low heat, without ever stirring.","The potatoes on top stay whole, those at the bottom collapse and thicken the broth. Cover with parsley."]} },

{ id:'asperges-a-la-flamande', c:'eu', lat:51.226, lon:4.415, base:4, prep:20, cook:25, diff:1, tags:['veg','fresh','festive'],
  art:{v:'plate',bg:'#2f3328',plate:'#f4ecd8',style:'salad',food:['#f0e8d0','#e8c46a','#f4f0e6','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Asperges à la flamande',en:'Asparagus à la flamande'},
  p:{fr:'Malines, Anvers, Belgique',en:'Mechelen, Antwerp, Belgium'},
  d:{fr:"Des asperges blanches sous un beurre fondu à l'œuf dur écrasé, que chacun mélange dans son assiette. Malines est la capitale belge de l'asperge blanche, cultivée sous butte pour rester pâle.",
     en:"White asparagus under melted butter with crushed hard-boiled egg, which each diner mixes on their own plate. Mechelen is Belgium's white asparagus capital, grown under ridges to stay pale."},
  i:[['white_asparagus',2,'kg'],['egg',6,'pc'],['butter',250,'g'],['parsley',1,'bunch'],['nutmeg',1,'pinch'],['lemon',1,'pc'],['potato',600,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Épluchez les asperges de la pointe vers la base, deux fois, et cassez le talon fibreux.","Faites cuire les épluchures 15 minutes dans l'eau salée : ce bouillon parfumé servira à pocher les asperges.","Pochez-les 15 minutes selon leur grosseur, puis égouttez-les sur un linge — jamais dans une passoire, elles se casseraient.","Faites fondre le beurre jusqu'à ce qu'il noisette à peine, hors du feu.","Écrasez les œufs durs à la fourchette dans le beurre tiède avec le persil, la muscade et le citron. Chacun mélange lui-même sur son assiette."],
     en:["Peel the asparagus from tip to base, twice over, and snap off the fibrous end.","Simmer the peelings for 15 minutes in salted water: this fragrant broth will poach the spears.","Poach them for 15 minutes depending on thickness, then drain on a cloth — never in a colander, they would break.","Melt the butter until it just begins to turn nutty, then take it off the heat.","Crush the hard-boiled eggs into the warm butter with the parsley, nutmeg and lemon. Each diner mixes it on their own plate."]} },

{ id:'rommegrot', c:'eu', lat:61.114, lon:7.086, base:4, prep:15, cook:35, diff:2, tags:['comfort','sweet','slow'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4ead4',style:'stew',food:['#f4f0e6','#e0b45a','#c9924a','#f0e0bc'],garnish:'#c9754a'},
  n:{fr:'Rømmegrøt',en:'Rømmegrøt'},
  p:{fr:'Sogndal, Norvège',en:'Sogndal, Norway'},
  d:{fr:"Une bouillie de crème aigre travaillée jusqu'à ce que le beurre se sépare et remonte en flaques dorées. On la sert avec ce beurre, du sucre et de la cannelle ; elle accompagnait les fêtes de moisson et les naissances.",
     en:"A porridge of sour cream worked until the butter separates and rises in golden pools. Served with that butter, sugar and cinnamon; it marked harvest feasts and births."},
  i:[['sour_cream',1,'l'],['flour',150,'g'],['whole_milk',500,'ml'],['sugar',80,'g'],['cinnamon',2,'tsp'],['salted_butter',60,'g'],['salt',null,'']],
  s:{fr:["Portez la crème aigre à frémissement dans une casserole à fond épais et laissez-la mijoter 10 minutes à couvert.","Versez la moitié de la farine en pluie en fouettant, et continuez de remuer : au bout de quelques minutes, le beurre commence à perler en surface.","Recueillez ce beurre à la cuillère et réservez-le : c'est lui qu'on versera sur la bouillie à la fin.","Ajoutez le reste de la farine, puis le lait chaud peu à peu, en fouettant jusqu'à obtenir une crème lisse et brillante.","Laissez cuire 15 minutes à feu doux, salez, et servez avec le beurre recueilli, le sucre et la cannelle."],
     en:["Bring the sour cream to a simmer in a heavy pan and let it bubble gently, covered, for 10 minutes.","Rain in half the flour while whisking, and keep stirring: after a few minutes the butter starts to bead on the surface.","Spoon off that butter and keep it: it is what will be poured over the porridge at the end.","Add the rest of the flour, then the hot milk little by little, whisking to a smooth glossy cream.","Cook for 15 minutes over low heat, salt it, and serve with the reserved butter, sugar and cinnamon."]} },

{ id:'kalakeitto-saaristo', c:'eu', lat:60.144, lon:21.560, base:4, prep:25, cook:30, diff:1, tags:['sea','soup','comfort'],
  art:{v:'bowl',bg:'#26404c',plate:'#f4ecd8',style:'soup',food:['#f4f0e6','#f0e8d0','#e0b45a','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Soupe de poisson de l’archipel',en:'Archipelago fish soup'},
  p:{fr:'Nauvo, archipel de Turku, Finlande',en:'Nagu, Turku archipelago, Finland'},
  d:{fr:"Une soupe de poissons blancs de la Baltique au lait et au piment de la Jamaïque, sans crème. Les îles de l'archipel finlandais en font la version pauvre et claire du lohikeitto, avec ce qui se pêche au filet.",
     en:"A soup of Baltic white fish with milk and allspice, without cream. The Finnish archipelago islands make it the plain, clear version of lohikeitto, with whatever the nets bring in."},
  i:[['whitefish',800,'g'],['potato',600,'g'],['onion',2,'pc'],['carrot',2,'pc'],['whole_milk',800,'ml'],['butter',80,'g'],['allspice',8,'pc'],['bay_leaf',2,'pc'],['dill',1,'bunch'],['rye_bread',6,'slice'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Levez les filets et faites un fumet avec les têtes et les arêtes, 20 minutes avec le laurier et le piment ; filtrez.","Faites suer l'oignon et la carotte au beurre sans coloration, puis ajoutez les pommes de terre en cubes.","Mouillez du fumet et laissez cuire 15 minutes.","Versez le lait, portez à frémissement — sans bouillir, il tournerait —, puis glissez les morceaux de poisson.","Coupez le feu et laissez pocher 8 minutes de chaleur résiduelle. Ajoutez une grande poignée d'aneth et servez avec du pain de seigle beurré."],
     en:["Fillet the fish and make a stock with the heads and bones for 20 minutes with the bay and allspice; strain it.","Sweat the onion and carrot in butter without colouring, then add the diced potatoes.","Moisten with the stock and cook for 15 minutes.","Pour in the milk and bring to a bare simmer — boiling would curdle it — then slide in the fish pieces.","Cut the heat and let them poach for 8 minutes in the residual warmth. Add a large handful of dill and serve with buttered rye bread."]} }
,
{ id:'ciorba-radauteana', c:'eu', lat:47.845, lon:25.918, base:6, prep:25, cook:60, diff:1, tags:['soup','poultry','comfort'],
  art:{v:'bowl',bg:'#2c3440',plate:'#f4ecd8',style:'soup',food:['#f0e8d0','#e8dcc0','#f4f0e6','#c9a878'],garnish:'#7fae6a'},
  n:{fr:'Ciorbă de Rădăuți',en:'Ciorbă rădăuțeană'},
  p:{fr:'Rădăuți, Bucovine, Roumanie',en:'Rădăuți, Bukovina, Romania'},
  d:{fr:"Une soupe de poulet blanchie à la crème et au jaune d'œuf, inventée en 1979 par une cuisinière de Rădăuți qui voulait une version douce de la soupe de tripes. Elle a conquis le pays en dix ans.",
     en:"A chicken soup whitened with cream and egg yolk, invented in 1979 by a cook in Rădăuți who wanted a gentle version of tripe soup. It conquered the country within a decade."},
  i:[['chicken_breast',700,'g'],['carrot',3,'pc'],['celery_root',1,'pc'],['parsnip',1,'pc'],['onion',2,'pc'],['heavy_cream',300,'ml'],['egg_yolk',4,'pc'],['garlic',10,'clove'],['white_wine_vinegar',60,'ml'],['parsley',4,'tbsp'],['bay_leaf',2,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Pochez le poulet 40 minutes avec les légumes entiers et le laurier, en écumant : le bouillon doit rester clair.","Retirez la volaille et taillez-la en fines lanières ; taillez la carotte en julienne et jetez le reste des légumes.","Pilez l'ail au sel avec deux cuillerées de bouillon.","Battez la crème et les jaunes, tempérez-les d'une louche de bouillon chaud versée en filet, puis liez la soupe hors du feu.","Rendez-la acidulée au vinaigre, ajoutez l'ail et le persil, et ne laissez plus jamais bouillir."],
     en:["Poach the chicken for 40 minutes with the whole vegetables and bay, skimming: the broth must stay clear.","Lift out the meat and cut it into fine strips; julienne the carrot and discard the other vegetables.","Pound the garlic with salt and two spoonfuls of broth.","Beat the cream and yolks, temper them with a ladle of hot broth trickled in, then thicken the soup off the heat.","Sharpen it with vinegar, add the garlic and parsley, and never let it boil again."]} },

{ id:'selsko-meso', c:'eu', lat:41.031, lon:21.335, base:6, prep:30, cook:90, diff:1, tags:['pork','bake','comfort'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'stew',food:['#8f5a3a','#c9754a','#e8dcb8','#e0913a'],garnish:'#7fae6a'},
  n:{fr:'Selsko meso',en:'Selsko meso'},
  p:{fr:'Prilep, Macédoine du Nord',en:'Prilep, North Macedonia'},
  d:{fr:"Du porc, des champignons et du fromage blanc de brebis cuits dans un poêlon de terre individuel, le tavče. « Viande du village » : chaque convive reçoit son plat, que l'on sort du four bouillonnant.",
     en:"Pork, mushrooms and sheep's white cheese baked in an individual earthenware pan, the tavče. 'Village meat': each guest gets their own dish, brought from the oven still bubbling."},
  i:[['pork_shoulder',800,'g'],['button_mushrooms',400,'g'],['onion',3,'pc'],['red_pepper',2,'pc'],['sheep_milk_cheese',250,'g'],['paprika',2,'tbsp'],['white_wine',150,'ml'],['sunflower_oil',80,'ml'],['ripe_tomato',300,'g'],['parsley',3,'tbsp'],['egg',2,'pc'],['savory',1,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Taillez le porc en fines lanières et faites-le saisir vivement à l'huile, par petites quantités, pour qu'il colore sans bouillir.","Ajoutez l'oignon en demi-lunes et le poivron, puis les champignons émincés, et laissez-les rendre leur eau.","Déglacez au vin blanc, ajoutez la tomate concassée, la sarriette et le paprika hors du feu.","Répartissez dans des poêlons de terre, émiettez le fromage par-dessus et cassez un demi-œuf sur chacun.","Enfournez 25 minutes à 220 °C : le dessus doit gratiner et le bord du poêlon crépiter. Servez dans le plat de cuisson."],
     en:["Cut the pork into fine strips and sear it briskly in oil, in small batches, so it colours rather than stews.","Add the onion in half-moons and the pepper, then the sliced mushrooms, and let them release their water.","Deglaze with white wine, add the crushed tomato, savory and paprika off the heat.","Divide between earthenware pans, crumble the cheese over and break half an egg onto each.","Bake for 25 minutes at 220°C: the top should gratinate and the rim of the pan crackle. Serve in the dish it cooked in."]} },

{ id:'kapama-bansko', c:'eu', lat:41.838, lon:23.488, base:8, prep:60, cook:210, diff:2, tags:['poultry','slow','festive'],
  art:{v:'pot',bg:'#2b2419',plate:'#f0e4c8',style:'stew',food:['#8f5a3a','#c9754a','#e8dcb8','#e0913a'],garnish:'#7fae6a'},
  n:{fr:'Kapama de Bansko',en:'Bansko kapama'},
  p:{fr:'Bansko, Bulgarie',en:'Bansko, Bulgaria'},
  d:{fr:"Quatre viandes, du riz et de la choucroute empilés dans une jarre scellée à la pâte et cuits trois heures au four du village. Kapama vient du turc kapamak, « couvrir » : rien ne doit s'échapper.",
     en:"Four meats, rice and sauerkraut packed into a jar sealed with dough and baked for three hours in the village oven. Kapama comes from the Turkish kapamak, 'to cover': nothing must escape."},
  i:[['chicken',800,'g'],['pork_shoulder',500,'g'],['veal_shoulder',400,'g'],['smoked_sausage',300,'g'],['sauerkraut',1.2,'kg'],['long_grain_rice',250,'g'],['onion',3,'pc'],['paprika',2,'tbsp'],['savory',2,'tbsp'],['black_peppercorns',1,'tbsp'],['bay_leaf',3,'pc'],['lard',80,'g'],['flour',300,'g'],['salt',null,'']],
  s:{fr:["Faites colorer séparément le poulet, le porc et le veau dans le saindoux, puis la saucisse en rondelles.","Faites revenir les oignons, ajoutez le paprika hors du feu et la sarriette.","Pressez la choucroute et tapissez-en le fond d'une jarre de terre ; alternez viandes, riz cru et choucroute jusqu'en haut.","Mouillez d'un litre du jus de choucroute allongé d'eau, sans dépasser le niveau des ingrédients.","Pétrissez une pâte de farine et d'eau, scellez-en le couvercle hermétiquement et enfournez 3 heures à 160 °C. On brise le sceau à table."],
     en:["Brown the chicken, pork and veal separately in the lard, then the sliced sausage.","Fry the onions, add the paprika off the heat and the savory.","Squeeze the sauerkraut and line the base of an earthenware jar with it; alternate meats, raw rice and sauerkraut to the top.","Moisten with a litre of sauerkraut juice let down with water, without going above the level of the ingredients.","Knead a dough of flour and water, seal the lid hermetically with it and bake for 3 hours at 160°C. The seal is broken at the table."]} }
];
